WITH base AS ( SELECT CAST(date_add('day', 4, date_trunc('week', CAST(a."date" AS DATE))) AS DATE) AS week_ending, a.expert_id AS agent_id, a.expert AS agent_name, a.site AS mascot, LOWER(a.icp_client) AS icp_client, LOWER(a.client) AS client, LOWER(a.subclient) AS subclient, a.tenure_group, a.coach, a.supervisor_id AS coach_id, CAST(a."date" AS DATE) AS as_of_date FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-07-18' AND DATE '2026-08-28' AND LOWER(a.icp_client) IN ( 'mob-at&t','mob-verizon','pss-at&t','pss-at&t nac','pss-verizon','xbox','mcafee' ) ), dedup AS ( SELECT week_ending, agent_id, agent_name, icp_client, client, subclient, max_by(mascot, as_of_date) AS mascot, max_by(tenure_group, as_of_date) AS tenure_group, max_by(coach, as_of_date) AS coach, max_by(coach_id, as_of_date) AS coach_id FROM base GROUP BY 1,2,3,4,5,6 ) SELECT week_ending, agent_id, agent_name, mascot, icp_client, client, subclient, tenure_group, coach, coach_id FROM dedup
